CREATE TABLE IF NOT EXISTS energy_readings (source TEXT NOT NULL,metric TEXT NOT NULL,ts TIMESTAMPTZ NOT NULL,value NUMERIC(18,6) NOT NULL,unit TEXT NOT NULL,quality TEXT NOT NULL DEFAULT 'observed' CHECK (quality IN ('observed','forecast','estimated')),metadata JSONB NOT NULL DEFAULT '{}'::jsonb,ingested_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY (source,metric,ts));
CREATE INDEX IF NOT EXISTS energy_readings_metric_ts_idx ON energy_readings(metric,ts DESC);
CREATE TABLE IF NOT EXISTS tariff_rates (id BIGSERIAL PRIMARY KEY,fuel TEXT NOT NULL CHECK (fuel IN ('electricity','gas')),price_p_per_kwh NUMERIC(12,5) NOT NULL CHECK (price_p_per_kwh>=0),standing_p_per_day NUMERIC(12,5) NOT NULL DEFAULT 0,valid_from DATE NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(fuel,valid_from));
CREATE TABLE IF NOT EXISTS experiments (id BIGSERIAL PRIMARY KEY,started_at TIMESTAMPTZ NOT NULL DEFAULT now(),ended_at TIMESTAMPTZ,category TEXT NOT NULL CHECK (category IN ('heating','hot_water','solar','other')),change_description TEXT NOT NULL,hypothesis TEXT NOT NULL DEFAULT '',comfort_notes TEXT NOT NULL DEFAULT '',baseline_notes TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
